// images
import a from "./a.png";
// images

// hooks and customHooks
import { useContext } from "react";
import { useTheme, themme } from "./CustomState";
import { weatherContextState, corddContext, dateContext } from "./Context/WeatherContext";
import { languageContext } from "./Context/WeatherContext";
import { useCustomEffectAxios } from "./EffectHook";
import { useLanguagehook, useSetTime } from "./EffectHook";
// hooks and customHooks

// external library
import { t } from "i18next";
import WindPowerIcon from "@mui/icons-material/WindPower";
import DeviceThermostatIcon from "@mui/icons-material/DeviceThermostat";
import WaterDropIcon from "@mui/icons-material/WaterDrop";
import WbTwilightIcon from "@mui/icons-material/WbTwilight";
import SunnyIcon from "@mui/icons-material/Sunny";
import Button from "@mui/material/Button";
// external library

export default function Card() {
  // screen width
  const screenWidth = window.innerWidth;

  // Card dimensions responsive
  const cardWidth = screenWidth > 1024 ? 500 : screenWidth * 0.95;
  const cardHeight = screenWidth > 1024 ? 400 : 'auto';
  const innerCardWidth = screenWidth > 1024 ? '90%' : '100%';
  const innerCardMaxHeight = screenWidth > 1024 ? 300 : 'auto';

  // language context
  const { lan, dispatch } = useContext(languageContext);
  useLanguagehook(lan.langue);

  // weather API states
  const { dateTime, setDateTime } = useContext(dateContext);
  const { weatherState } = useContext(weatherContextState);
  const { setCord } = useContext(corddContext);

  // theme
  const [colorTheme, setColorTheme] = useTheme();

  // custom hooks
  useCustomEffectAxios();
  useSetTime();

  // temperature and weather info
  const Temp = Math.round(weatherState.temp - 273.15);
  const Wilaya = weatherState.wilaya;
  const Min = Math.round(weatherState.min - 273.15);
  const Max = Math.round(weatherState.max - 273.15);
  const Humidity = weatherState.hum;
  const windSpeed = Math.round(weatherState.Wind * 3.6);
  const Desc = weatherState.desc;
  const yes = new Date(weatherState.rise * 1000);
  const yees = new Date(weatherState.set * 1000);
  const vraiDate = yes.toLocaleTimeString([], { hour: "2-digit", minute: "2-digit", hour12: false });
  const vraiset = yees.toLocaleTimeString([], { hour: "2-digit", minute: "2-digit", hour12: false });

  // handlers
  const handleOranMeteo = () => setCord({ lt: 35.7, lg: -0.64 });
  const handleTlemcenMeteo = () => setCord({ lt: 34.89, lg: -1.32 });
  const handleTemouchentMeteo = () => setCord({ lt: 35.3, lg: -1.14 });
  const handleBelabbesMeteo = () => setCord({ lt: 35.26, lg: -0.56 });
  const handlePrimary = () => setColorTheme("primary");
  const handleSecondary = () => setColorTheme("secondary");
  const handleLanguage = () => dispatch({ type: "langue" });

  return (
    <div style={{ minHeight: "100vh", background: themme.palette[colorTheme].bdy, padding: "20px 0" }}>
      <h1 style={{ textAlign: "center" }}>Welcome to Dino</h1>

      {/* Theme buttons + image */}
      <div style={{ display: "flex", justifyContent: "center", alignItems: "center", gap: "20px", flexWrap: "wrap", marginBottom: "20px" }}>
        <Button variant="contained" color="secondary" onClick={handleSecondary}>{t("pink mode")}</Button>
        <img src={a} style={{ width: "200px" }} alt="cloud" />
        <Button variant="contained" color="primary" onClick={handlePrimary}>{t("blue mode")}</Button>
      </div>

      {/* City buttons */}
      <div style={{ display: "flex", flexWrap: "wrap", justifyContent: "center", gap: "10px", marginBottom: "20px" }}>
        <Button variant="contained" onClick={handleTemouchentMeteo} color={colorTheme}>{t("Aïn Temouchent")}</Button>
        <Button variant="contained" onClick={handleOranMeteo} color={colorTheme}>{t("Oran")}</Button>
        <Button variant="contained" onClick={handleTlemcenMeteo} color={colorTheme}>{t("Tlemcen")}</Button>
        <Button variant="contained" onClick={handleBelabbesMeteo} color={colorTheme}>{t("Sidi Bel Abbes")}</Button>
      </div>

      {/* Card */}
      <div style={{ width: cardWidth, height: cardHeight, margin: "0 auto" }}>
        <div style={{
          background: themme.palette[colorTheme].light,
          width: innerCardWidth,
          margin: "auto",
          borderRadius: "10px",
          maxHeight: innerCardMaxHeight,
          boxShadow: `10px 30px 20px ${themme.palette[colorTheme].shdw}`,
          padding: "15px",
        }}>
          {/* Header: Wilaya + Time */}
          <div style={{
            display: "flex",
            justifyContent: "space-between",
            alignItems: "center",
            color: "white",
            direction: lan.arabe ? 'rtl' : 'ltr',
          }}>
            <h1 style={{ margin: lan.arabe ? "0 20px 0 0" : "0 0 0 20px" }}>{Wilaya ? t(Wilaya) : ""}</h1>
            <h4 style={{ margin: lan.arabe ? "0 0 0 20px" : "0 20px 0 0" }}>{dateTime}</h4>
          </div>

          <hr style={{ borderColor: "white" }} />

          {/* Main weather info */}
          <div style={{ display: "flex", justifyContent: "space-between", color: "white", flexWrap: "wrap", direction: lan.arabe ? 'rtl' : 'ltr' }}>
            <div style={{ margin: lan.arabe ? "0 20px 10px 0" : "0 0 10px 20px", textAlign: lan.arabe ? "right" : "left" }}>
              <h3>{t(Desc)}</h3>
              <img src={`https://openweathermap.org/img/wn/${weatherState.icoon}@2x.png`} alt="icon" />
            </div>
            <div style={{ margin: lan.arabe ? "0 0 10px 20px" : "0 20px 10px 0" }}>
              <h1><DeviceThermostatIcon /> {Temp}º</h1>
              <h3>{t("min")} {Min} | {t("max")} {Max}</h3>
            </div>
          </div>

          {/* Footer: Other infos */}
          <div style={{
            borderRadius: "8px",
            background: themme.palette[colorTheme].dark,
            display: "flex",
            flexWrap: "wrap",
            color: "white",
            justifyContent: "space-around",
            alignItems: "center",
            padding: "10px 0",
            gap: "10px"
          }}>
            <h3 style={{ display: "flex", alignItems: "center", gap: "5px" }}>
              <SunnyIcon style={{ color: "yellow" }} /> {vraiDate}
            </h3>
            <h3 style={{ display: "flex", alignItems: "center", gap: "5px" }}>
              <WbTwilightIcon style={{ color: "yellow" }} /> {vraiset}
            </h3>
            <h3 style={{ display: "flex", alignItems: "center", gap: "3px" }}>
              <WaterDropIcon /> {Humidity}%
            </h3>
            <h3 style={{ display: "flex", alignItems: "center", gap: "5px" }}>
              <WindPowerIcon /> {windSpeed} {t("km")}
            </h3>
            <Button variant="contained" color={colorTheme} onClick={handleLanguage}>{t("Arabic")}</Button>
          </div>
        </div>
      </div>
    </div>
  );
}
